var t=`0415-boxty`;var n=`world-0415`;var i=`IE`;var l=`northern-europe`;var r=4;var a=31;var s={en:`Boxty`,ua:`Боксті`};var u={en:`A traditional dish from Ireland, centered on potato, yellow onion, all-purpose flour, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірландія. Основні складники: картопля, жовта цибуля, пшеничне борошно універсальне, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:8,i:[[`potato`,600,`g`],[`yellow-onion`,90,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`all-purpose-flour`,125,`g`],[`chicken-egg`,1,`pcs`],[`buttermilk`,160,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`unsalted-butter`,60,`g`],[`sunflower-oil`,30,`ml`]]}];var d={slug:t,id:n,country:`IE`,region:l,servings:4,minutes:31,title:s,text:u,steps:g};export{i as country,d as default,n as id,a as minutes,l as region,r as servings,t as slug,g as steps,u as text,s as title};